// Offline support: precache the whole app on install, then serve from cache.
// sw-manifest.js (generated by tools/build-sw.mjs) lists every file plus a
// content hash, so any change to the app produces a new cache version.
importScripts('sw-manifest.js');

const { version, files } = self.PRECACHE;
const CACHE = `pocket-arcade-${version}`;

self.addEventListener('install', (event) => {
  event.waitUntil(precache());
  // First install takes over straight away; updates wait for the page to ask.
  if (!self.registration.active) self.skipWaiting();
});

// Download every file into the new cache a few at a time, telling open pages
// how far along it is so they can show a progress bar for updates.
async function precache() {
  const cache = await caches.open(CACHE);
  const total = files.length;
  let done = 0;
  const report = async () => {
    const pages = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    for (const page of pages) {
      page.postMessage({ type: 'UPDATE_PROGRESS', version: self.PRECACHE.appVersion, done, total });
    }
  };
  await report();
  const queue = files.slice();
  const fetchNext = async () => {
    while (queue.length) {
      const file = queue.shift();
      const res = await fetch(new Request(file, { cache: 'reload' }));
      if (!res.ok) throw new Error(`precache ${file}: ${res.status}`);
      await cache.put(file, res);
      done++;
      await report();
    }
  };
  await Promise.all(Array.from({ length: 6 }, fetchNext));
}

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('pocket-arcade-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('message', (event) => {
  const type = event.data && event.data.type;
  if (type === 'SKIP_WAITING') self.skipWaiting();
  // Lets the page tell the player which version is waiting to install.
  if (type === 'GET_VERSION') event.ports[0]?.postMessage(self.PRECACHE.appVersion);
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  event.respondWith(
    caches.open(CACHE).then(async (cache) => {
      const hit = await cache.match(req, { ignoreSearch: true });
      if (hit) return hit;
      if (req.mode === 'navigate') {
        const shell = await cache.match('./');
        if (shell) return shell;
      }
      return fetch(req);
    }),
  );
});
